export const theme =
  "/* Every loader's colours, from Tecton's tokens. The shell's build writes this into index.html,\n   where the loading screen paints before any stylesheet arrives, so each token falls back to its\n   own value for the mode; examples/loaders shows every loader in these colours too.\n\n   An element with the class `loader-theme` gives the loaders inside it their colours: the page's\n   background, text, secondary text and primary accent, as `--loader-*`, and each loader's own\n   properties from those. */\n.loader-theme {\n  --loader-bg: var(--tecton-color-bg-default, #1d1c1f);\n  --loader-text: var(--tecton-color-text-primary, #f6f5f8);\n  --loader-muted: var(--tecton-color-text-secondary, #a7a2ac);\n  /* Tecton's primary purple. In dark mode the primary is violet-220, a fill made to sit\n   behind white text, which vanishes as a line on this ground; a higher-contrast step of the\n   same ramp is the dark mode's foreground for it. */\n  --loader-accent: var(--tecton-palette-violet-460, #8e8199);\n}\nhtml:not(.dark) .loader-theme {\n  --loader-bg: var(--tecton-color-bg-default, #f6f4f7);\n  --loader-text: var(--tecton-color-text-primary, #21172a);\n  --loader-muted: var(--tecton-color-text-secondary, #604e6e);\n  /* The primary itself: mauve-680, the colour of Tecton's primary actions. */\n  --loader-accent: var(--tecton-color-action-primary-bg, #644a78);\n}\n\n/* <drill-bit-loader>. On a light page a glow reads as a smudge, so it becomes a faint wash\n   of the accent, the grid darkens, and the grain and the warm pool go. */\n.loader-theme {\n  --drill-background: var(--loader-bg);\n  --drill-accent: var(--loader-accent);\n  --drill-line-color: var(--loader-muted);\n  --drill-label-color: var(--loader-muted);\n  --drill-label-strong: var(--loader-text);\n  --drill-font: 'IBM Plex Mono', ui-monospace, SFMono-Regular, Menlo, monospace;\n}\nhtml:not(.dark) .loader-theme {\n  --drill-glow: color-mix(in srgb, var(--loader-accent) 7%, transparent);\n  --drill-ambient: transparent;\n  --drill-grid-color: rgba(33, 23, 42, 0.035);\n  --drill-grain-opacity: 0;\n}\n\n/* <well-log-loader>. On a light page the texture and the vignette read as grey smudges, so\n   both nearly go. */\n.loader-theme {\n  --well-log-bg: var(--loader-bg);\n  --well-log-ink: var(--loader-text);\n  --well-log-accent: var(--loader-accent);\n  --well-log-font: 'IBM Plex Mono', ui-monospace, SFMono-Regular, Menlo, monospace;\n  --well-log-vignette: 0.7;\n}\nhtml:not(.dark) .loader-theme {\n  --well-log-vignette: 0.35;\n  --well-log-texture: 0.25;\n}\n\n/* The STRATUM loaders (src/loaders/stratum/), themed as the drill bit is. On a light page a\n   glow reads as a smudge, so it is a faint wash of the accent, and the grain and the warm\n   pool go. */\n.loader-theme {\n  --stratum-bg: var(--loader-bg);\n  --stratum-glow: color-mix(in srgb, var(--loader-bg), #fff 6%);\n  --stratum-accent: var(--loader-accent);\n  --stratum-ring-color: var(--loader-muted);\n  --stratum-line-color: color-mix(in srgb, var(--loader-muted) 45%, transparent);\n  --stratum-label-color: var(--loader-muted);\n  --stratum-font: 'IBM Plex Mono', ui-monospace, SFMono-Regular, Menlo, monospace;\n}\nhtml:not(.dark) .loader-theme {\n  --stratum-glow: color-mix(in srgb, var(--loader-accent) 7%, transparent);\n  --stratum-ambient: transparent;\n  --stratum-grid-color: rgba(33, 23, 42, 0.05);\n  --stratum-grain-opacity: 0;\n}\n\n/* The oil-and-gas loaders (src/loaders/oil-and-gas/). On a light page the edges would darken\n   to a grey smudge, so they do not. */\n.loader-theme {\n  --og-background: var(--loader-bg);\n  --og-ink: var(--loader-text);\n  --og-accent: var(--loader-accent);\n  --og-font: 'IBM Plex Mono', ui-monospace, SFMono-Regular, Menlo, monospace;\n  --og-vignette: rgba(0, 0, 0, 0.5);\n}\nhtml:not(.dark) .loader-theme {\n  --og-vignette: transparent;\n}\n\n/* <bounce-loader>. The logo keeps its own red in both modes; on a light page its shadow is\n   lighter, since red blurred on white reads as a pink smudge. */\n.loader-theme {\n  --bounce-background: var(--loader-bg);\n}\nhtml:not(.dark) .loader-theme {\n  --bounce-shadow-opacity: 0.18;\n}\n"

